// The catalog of the game's five standard modules, generated by tools/catalog/generate.mjs.

import data from "../data/catalog-2.1.24.json" with { type: "json" };
import { createCatalog } from "./catalog.ts";
import type { Catalog, CatalogData } from "./types.ts";

export const STANDARD_CATALOG_VERSION = "2.1.24";

let cached: Catalog | undefined;

/** Factorio 2.1.24 with base, elevated-rails, recycler, quality and space-age. The result is shared; treat it as immutable. */
export function loadStandardCatalog(): Catalog {
  cached ??= createCatalog(data as unknown as CatalogData);
  return cached;
}
